<?php
require_once __DIR__ . '/config.php';

function rows(string $sql): array { try { return db()->query($sql)->fetch_all(MYSQLI_ASSOC); } catch (Throwable $e) { return []; } }
function total(string $sql): int { try { return (int) ((db()->query($sql)->fetch_assoc() ?: [])['total'] ?? 0); } catch (Throwable $e) { return 0; } }
function rupee($n): string { $v = (float) $n; return $v > 0 ? 'Rs. ' . number_format($v, 0) : 'Free'; }
function abbr(string $s): string { $p = preg_split('/\s+/', trim($s)) ?: []; $o = ''; foreach ($p as $x) { if ($x !== '') $o .= strtoupper(substr($x, 0, 1)); if (strlen($o) >= 3) break; } return $o ?: 'GN'; }
function exam_logo(?string $slug, string $name = ''): string { $slug = trim((string) $slug); if ($slug === '') { $slug = strtolower(trim(preg_replace('/[^a-z0-9]+/i', '-', $name), '-')); } foreach (['svg','png','jpg','jpeg','webp'] as $ext) { $rel = 'uploads/exam-logos/' . $slug . '.' . $ext; if (is_file(__DIR__ . '/' . $rel)) { return app_url($rel); } } return ''; }

$courses = rows("SELECT c.id,c.title,c.short_description,c.price,c.original_price,c.thumbnail_path,c.course_level,c.course_language,c.duration,c.price_unit price_type,COALESCE(cat.name,c.category,'Course') category_name,COALESCE(u.full_name,'Instructor') instructor_name,(SELECT COUNT(*) FROM instructor_course_contents cc WHERE cc.course_id=c.id) modules,(SELECT COUNT(*) FROM student_course_likes cl WHERE cl.course_id=c.id) likes,(SELECT COUNT(*) FROM student_course_enrollments se WHERE se.course_id=c.id) learners FROM instructor_courses c LEFT JOIN course_categories cat ON cat.id=c.category_id LEFT JOIN users u ON u.id=c.instructor_id WHERE c.status='published' ORDER BY c.featured DESC,c.id DESC LIMIT 24");
$courseCats = rows("SELECT COALESCE(cat.name,c.category,'General') name,COUNT(*) count FROM instructor_courses c LEFT JOIN course_categories cat ON cat.id=c.category_id WHERE c.status='published' GROUP BY name ORDER BY count DESC,name LIMIT 8");
$examCats = rows("SELECT c.id,c.name,c.slug,(SELECT COUNT(*) FROM gov_exam_categories ch WHERE ch.parent_id=c.id AND ch.status='active') subcategories,(SELECT COUNT(*) FROM gov_exam_mock_tests m WHERE m.status='published' AND (m.category_id=c.id OR m.subcategory_id=c.id)) mocks,(SELECT COUNT(q.id) FROM gov_exam_mock_questions q INNER JOIN gov_exam_mock_tests m ON m.id=q.mock_test_id WHERE q.status='active' AND m.status='published' AND (m.category_id=c.id OR m.subcategory_id=c.id)) questions FROM gov_exam_categories c WHERE c.status='active' AND c.parent_id IS NULL ORDER BY mocks DESC,questions DESC,c.name LIMIT 12");
$mocks = rows("SELECT m.id,m.title,m.duration_minutes,c.name category_name,c.slug category_slug,s.name subcategory_name,s.slug subcategory_slug,(SELECT COUNT(*) FROM gov_exam_mock_questions q WHERE q.mock_test_id=m.id AND q.status='active') question_count FROM gov_exam_mock_tests m LEFT JOIN gov_exam_categories c ON c.id=m.category_id LEFT JOIN gov_exam_categories s ON s.id=m.subcategory_id WHERE m.status='published' ORDER BY m.id DESC LIMIT 8");
$docs = rows("SELECT d.id,d.title,d.description,d.price,COALESCE(s.name,c.name,'Study') category_name FROM gov_exam_documents d LEFT JOIN gov_exam_categories c ON c.id=d.category_id LEFT JOIN gov_exam_categories s ON s.id=d.subcategory_id WHERE d.status='published' ORDER BY d.id DESC LIMIT 6");
$live = rows("SELECT id,class_title,course_title,batch_name,instructor_name,class_date,starts_at,duration_minutes,class_status FROM live_classes ORDER BY id DESC LIMIT 4");
$instructors = rows("SELECT COALESCE(u.full_name,'Instructor') name,COUNT(c.id) courses FROM users u INNER JOIN instructor_courses c ON c.instructor_id=u.id AND c.status='published' GROUP BY u.id,u.full_name ORDER BY courses DESC,u.full_name LIMIT 4");
$plans = rows("SELECT plan_name,monthly_price,description FROM student_plans WHERE status IN ('active','published') ORDER BY monthly_price ASC LIMIT 1");

$stats = [
    ['Courses', total("SELECT COUNT(*) total FROM instructor_courses WHERE status='published'")],
    ['Mock Tests', total("SELECT COUNT(*) total FROM gov_exam_mock_tests WHERE status='published'")],
    ['Questions', total("SELECT COUNT(*) total FROM gov_exam_mock_questions WHERE status='active'")],
    ['Exam Groups', total("SELECT COUNT(*) total FROM gov_exam_categories WHERE status='active' AND parent_id IS NULL")],
];
$topCourse = $courses[0]['title'] ?? 'Python Full Stack Program';
$courseGroups = [];
foreach ($courses as $courseRow) {
    $key = trim((string) ($courseRow['category_name'] ?? 'General')) ?: 'General';
    if (!isset($courseGroups[$key])) {
        $courseGroups[$key] = ['category' => $key, 'items' => []];
    }
    $courseGroups[$key]['items'][] = $courseRow;
}
$courseGroups = array_values($courseGroups);
if ($courses) {
    array_unshift($courseGroups, ['category' => 'View All', 'items' => array_slice($courses, 0, 8)]);
}
$mockGroups = [];
$mockTabCategories = rows("SELECT c.id,c.name,c.slug,COUNT(DISTINCT m.id) mocks FROM gov_exam_categories c LEFT JOIN gov_exam_categories ch ON ch.parent_id=c.id LEFT JOIN gov_exam_mock_tests m ON m.status='published' AND (m.category_id=c.id OR m.subcategory_id=c.id OR m.category_id=ch.id OR m.subcategory_id=ch.id) WHERE c.status='active' AND c.parent_id IS NULL GROUP BY c.id,c.name,c.slug HAVING mocks>0 ORDER BY mocks DESC,c.name LIMIT 24");
foreach ($mockTabCategories as $catRow) {
    $catId = (int) ($catRow['id'] ?? 0);
    if ($catId <= 0) {
        continue;
    }
    $items = rows("SELECT m.id,m.title,m.duration_minutes,c.name category_name,c.slug category_slug,s.name subcategory_name,s.slug subcategory_slug,(SELECT COUNT(*) FROM gov_exam_mock_questions q WHERE q.mock_test_id=m.id AND q.status='active') question_count FROM gov_exam_mock_tests m LEFT JOIN gov_exam_categories c ON c.id=m.category_id LEFT JOIN gov_exam_categories s ON s.id=m.subcategory_id WHERE m.status='published' AND (m.category_id={$catId} OR m.subcategory_id={$catId} OR m.category_id IN (SELECT id FROM gov_exam_categories WHERE parent_id={$catId}) OR m.subcategory_id IN (SELECT id FROM gov_exam_categories WHERE parent_id={$catId})) ORDER BY m.id DESC LIMIT 8");
    if ($items) {
        $mockGroups[] = ['category' => $catRow, 'items' => $items];
    }
}
if ($mocks) {
    array_unshift($mockGroups, ['category' => ['name' => 'View All', 'slug' => 'all-exams'], 'items' => array_slice($mocks, 0, 8)]);
}
if (!$mockGroups && $mocks) {
    $mockGroups[] = ['category' => ['name' => 'View All', 'slug' => 'all-exams'], 'items' => $mocks];
}
$pageTitle = app_name() . ' - Learning Platform';
?>
