nter!important;margin:0 0 7px!important;white-space:nowrap!important}.coursePrice del{font-size:9px!important;color:#94a3b8!important}.coursePrice b{font-size:13px!important;color:#07111f!important;font-weight:800!important}.save{display:none!important}.view,.testBtn{height:31px!important;border-radius:9px!important;background:#ffdf3b!important;color:#050505!important;font-size:11px!important;font-weight:700!important;box-shadow:inset 0 -1px 0 rgba(0,0,0,.08)!important}

