tice</div><div class="heroStat"><span><b><?= h(number_format($stats[0][1] ?? 0)); ?></b>Courses</span><span><b><?= h(number_format($stats[1][1] ?? 0)); ?></b>Tests</span><span><b><?= h(number_format($stats[2][1] ?? 0)); ?></b>Questions</span></div></div><div class="vcard vphone"><div class="vrow"><span class="ava">GN</span><div><b>Gyan Nexa</b><br><small>Learner Account</small></div></div><div class="notice">Enroll me for <?= h($topCourse); ?>!</div><span class="start">Start Learning</span></div></div></div></section>
