<script>
function wireTabs(tabSelector,panelSelector){document.querySelectorAll(tabSelector).forEach(function(tab){tab.addEventListener('click',function(){var id=tab.getAttribute('data-target');if(!id){return}document.querySelectorAll(tabSelector).forEach(function(x){x.classList.remove('active')});document.querySelectorAll(panelSelector).forEach(function(x){x.classList.remove('active')});tab.classList.add('active');var panel=document.getElementById(id);if(panel){panel.classList.add('active')}})});}wireTabs('.mockTab','.mockPanel');wireTabs('.courseTab','.coursePanel');
function infoSlider(){var wrap=document.querySelector(".infoSlider .infoGrid");var dots=document.querySelectorAll(".infoDot");if(!wrap||!dots.length){return}var current=0;function show(i){current=i;wrap.scrollTo({left:wrap.clientWidth*i,behavior:"smooth"});dots.forEach(function(d,x){d.classList.toggle("active",x===i)})}dots.forEach(function(dot){dot.addEventListener("click",function(){show(parseInt(dot.getAttribute("data-info")||"0",10))})});setInterval(function(){if(window.innerWidth>720){return}show((current+1)%dots.length)},3600)}infoSlider();function mobileDrawer(){var body=document.body;var open=document.querySelector(".menuBtn");var close=document.querySelector(".drawerClose");var shade=document.querySelector(".drawerShade");var links=document.querySelectorAll(".drawerLinks a");function hide(){body.classList.remove("drawerOpen")}if(open){open.addEventListener("click",function(){body.classList.add("drawerOpen")})}if(close){close.addEventListener("click",hide)}if(shade){shade.addEventListener("click",hide)}links.forEach(function(a){a.addEventListener("click",hide)})}mobileDrawer();function faqAccordion(){document.querySelectorAll(".faqItem").forEach(function(item){item.addEventListener("toggle",function(){if(!item.open){return}document.querySelectorAll(".faqItem").forEach(function(other){if(other!==item){other.open=false}})})})}faqAccordion();function heroSlider(){var slides=document.querySelectorAll(".heroSlide");var dots=document.querySelectorAll(".heroDot");if(!slides.length||!dots.length){return}var current=0;function show(i){current=i;slides.forEach(function(s,x){s.classList.toggle("active",x===i)});dots.forEach(function(d,x){d.classList.toggle("active",x===i)})}dots.forEach(function(dot){dot.addEventListener("click",function(){show(parseInt(dot.getAttribute("data-slide")||"0",10))})});setInterval(function(){show((current+1)%slides.length)},4200)}heroSlider();</script>
</body>
